// The left navigation sidebar.
// Always dark regardless of light/dark mode (like BankDash reference).

"use client";

import Link from "next/link";
import Image from "next/image";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard,
  Globe,
  ShieldCheck,
  Mail,
  Bell,
  BarChart3,
  Settings,
  CreditCard,
  LogOut,
  Inbox,
} from "lucide-react";
import { useUser, useClerk } from "@clerk/nextjs";
import { cn } from "@/lib/utils";

// Navigation items — each maps to a route
const NAV_ITEMS = [
  {
    section: "Main",
    items: [
      { label: "Dashboard", icon: LayoutDashboard, href: "/dashboard" },
      { label: "Domains", icon: Globe, href: "/dashboard/domains" },
      { label: "Compliance", icon: ShieldCheck, href: "/dashboard/compliance" },
      { label: "Unsubscribe", icon: Mail, href: "/dashboard/unsubscribe" },
    ],
  },
  {
    section: "Monitor",
    items: [
      { label: "Alerts", icon: Bell, href: "/dashboard/alerts", badge: 3 },
      { label: "Analytics", icon: BarChart3, href: "/dashboard/analytics" },
    ],
  },
  {
    section: "Account",
    items: [
      { label: "Billing", icon: CreditCard, href: "/dashboard/billing" },
      { label: "Settings", icon: Settings, href: "/dashboard/settings" },
    ],
  },
];

export default function Sidebar() {
  const pathname = usePathname();

  return (
    // Sidebar background is always dark — uses fixed dark colors
    // not the theme variables so it stays dark in both modes
    <aside className="w-55 min-w-55 bg-[#0B1120] flex flex-col border-r border-white/6 ">
      {/* Brand */}
      <div className="flex items-center gap-2.5 px-5 py-6 border-b border-white/6">
        <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shrink-0">
          <Inbox className="w-4 h-4 text-white" />
        </div>
        <span className="text-white font-extrabold text-[15px] tracking-tight">
          Inbox<span className="text-blue-500">Rules</span>
        </span>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-3 py-4 space-y-5 overflow-y-auto">
        {NAV_ITEMS.map((section) => (
          <div key={section.section}>
            {/* Section label */}
            <p
              className="text-[10px] font-bold uppercase tracking-widest
                          text-slate-500 px-3 mb-1.5"
            >
              {section.section}
            </p>

            {/* Items */}
            <div className="space-y-0.5">
              {section.items.map((item) => {
                const isActive = pathname === item.href;
                const Icon = item.icon;

                return (
                  <Link
                    key={item.href}
                    href={item.href}
                    className={cn(
                      "flex items-center gap-2.5 px-3 py-2 rounded-lg",
                      "text-[13px] font-medium transition-all duration-150",
                      isActive
                        ? // Active: solid blue background
                          "bg-blue-600 text-white"
                        : // Inactive: muted text, hover lightens background
                          "text-slate-400 hover:text-slate-100 hover:bg-white/6",
                    )}
                  >
                    <Icon className="w-4 h-4 shrink-0" />
                    <span className="flex-1">{item.label}</span>

                    {/* Alert badge */}
                    {"badge" in item && item.badge ? (
                      <span
                        className="bg-red-500 text-white text-[10px]
                                       font-bold px-1.5 py-0.5 rounded-full
                                       font-mono leading-none"
                      >
                        {item.badge}
                      </span>
                    ) : null}
                  </Link>
                );
              })}
            </div>
          </div>
        ))}
      </nav>

      {/* User section at bottom */}
      <SidebarUser />
    </aside>
  );
}

function SidebarUser() {
  const { user } = useUser();
  const { signOut } = useClerk();

  if (!user) return null;

  // Get initials from user's name
  const initials =
    user.firstName && user.lastName
      ? `${user.firstName[0]}${user.lastName[0]}`.toUpperCase()
      : user.emailAddresses[0]?.emailAddress?.substring(0, 2).toUpperCase() ||
        "U";

  return (
    <div
      style={{
        padding: "12px 10px",
        borderTop: "1px solid rgba(255,255,255,0.05)",
      }}
    >
      <div
        className="flex items-center gap-2.5 rounded-xl cursor-pointer"
        style={{ padding: "9px 10px" }}
        onClick={() => signOut({ redirectUrl: "/sign-in" })}
        title="Sign out"
      >
        {/* Avatar — use Clerk profile image if available */}
        {user.imageUrl ? (
          <Image
            src={user.imageUrl}
            alt={user.firstName || "User"}
            width={34}
            height={34}
            style={{
              borderRadius: "50%",
              objectFit: "cover",
              flexShrink: 0,
            }}
          />
        ) : (
          <div
            style={{
              width: 34,
              height: 34,
              borderRadius: "50%",
              background: "linear-gradient(135deg, #2563EB, #7C3AED)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 12,
              fontWeight: 700,
              color: "white",
              flexShrink: 0,
            }}
          >
            {initials}
          </div>
        )}

        <div style={{ flex: 1, minWidth: 0 }}>
          <p style={{ color: "#CBD5E1", fontSize: 13, fontWeight: 600 }}>
            {user.firstName
              ? `${user.firstName} ${user.lastName || ""}`.trim()
              : user.emailAddresses[0]?.emailAddress}
          </p>
          <p style={{ color: "#1E3A5F", fontSize: 11, marginTop: 1 }}>
            Pro Plan
          </p>
        </div>

        <LogOut size={14} color="#1E3A5F" />
      </div>
    </div>
  );
}
